[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$RunDirectory,[Parameter(Mandatory=$true)][string]$Output)
$ErrorActionPreference='Stop'; $run=(Resolve-Path $RunDirectory).Path; $m=Get-Content (Join-Path $run 'ifc-manifest.json') -Raw | ConvertFrom-Json; $repo=(Resolve-Path (Join-Path $PSScriptRoot '../..')).Path; $ifc=Join-Path $repo ($m.ifc -replace '/', '\'); if(-not(Test-Path $ifc)){throw "Missing IFC $ifc"}; $bytes=[IO.File]::ReadAllBytes($ifc); $text=[Text.Encoding]::ASCII.GetString($bytes); $hash=(Get-FileHash $ifc -Algorithm SHA256).Hash; $walls=([regex]::Matches($text,'IFCWALL(STANDARDCASE)?\(')).Count; $slabs=([regex]::Matches($text,'IFCSLAB\(')).Count; $checks=@([pscustomobject]@{name='manifest_ifc_hash';pass=($hash -eq $m.ifc_sha256);detail=$hash},[pscustomobject]@{name='non_empty';pass=($bytes.Length -gt 0);detail="$($bytes.Length) bytes"},[pscustomobject]@{name='step_header';pass=$text.StartsWith('ISO-10303-21;');detail='ISO-10303-21'},[pscustomobject]@{name='ifc2x3_schema';pass=($text -match 'IFC2X3');detail='IFC2X3'},[pscustomobject]@{name='wall_entities';pass=($walls -ge 42);detail="$walls IFCWALL entities"},[pscustomobject]@{name='floor_entities';pass=($slabs -ge 3);detail="$slabs IFCSLAB entities"}); $r=[ordered]@{schema='forever-home-main-floor-floor-plate-ifc-validation-v1';run_directory=$run;ifc=$ifc;pass=(@($checks|Where-Object {-not $_.pass}).Count -eq 0);checks=$checks;limitations=@('Export integrity and entity presence only; provisional floor type is not a selected assembly.','Not a code, structural, professional or construction approval.')}; $r|ConvertTo-Json -Depth 8|Set-Content $Output -Encoding utf8; $checks|Format-Table -AutoSize; Write-Host "pass : $($r.pass); checks : $(@($checks|Where-Object pass).Count)/$($checks.Count)"; if(-not $r.pass){exit 1}
